/** One `key: value` line of a frontmatter block; a YAML list (`- a` lines or `[a, b]`) gives an array. */
type FrontmatterProperty = { key: string; value: string | readonly string[] }

type Frontmatter = {
  /** Where the block starts and ends in the Markdown (the opening `---` to the end of the closing fence's line). */
  from: number
  to: number
  /** The text between the fences, as written. */
  raw: string
  properties: FrontmatterProperty[]
}

const OPEN = /^---[ \t]*$/
const CLOSE = /^(?:---|\.\.\.)[ \t]*$/
const BOM = "﻿"

/** The leading YAML block's bounds, or `null`: it needs `---` on the first line and a closing `---` or `...` line. */
function frontmatterBounds(markdown: string) {
  const from = markdown.startsWith(BOM) ? BOM.length : 0
  let lineStart = from
  let contentFrom = -1
  while (lineStart <= markdown.length) {
    const newline = markdown.indexOf("\n", lineStart)
    const lineEnd = newline < 0 ? markdown.length : newline
    const text = markdown.slice(lineStart, lineEnd).replace(/\r$/, "")
    if (contentFrom < 0) {
      if (!OPEN.test(text)) return null
      contentFrom = newline < 0 ? lineEnd : newline + 1
    } else if (CLOSE.test(text)) {
      const breakSize = markdown[lineStart - 2] === "\r" ? 2 : 1
      const contentTo = lineStart === contentFrom ? contentFrom : lineStart - breakSize
      return { from, to: lineStart + text.length, contentFrom, contentTo }
    }
    if (newline < 0) return null
    lineStart = newline + 1
  }
  return null
}

function unquote(value: string) {
  const text = value.trim()
  if (text.length >= 2 && (text[0] === '"' || text[0] === "'") && text.at(-1) === text[0]) return text.slice(1, -1)
  return text.replace(/\s+#.*$/, "")
}

function splitInline(list: string) {
  const items: string[] = []
  let current = ""
  let quote = ""
  for (const char of list) {
    if (quote) {
      if (char === quote) quote = ""
      current += char
    } else if (char === '"' || char === "'") {
      quote = char
      current += char
    } else if (char === ",") {
      items.push(current)
      current = ""
    } else {
      current += char
    }
  }
  if (current.trim() || items.length) items.push(current)
  return items.map(unquote).filter((item) => item !== "")
}

/**
 * Reads the `key: value` lines, lists and `|`/`>` blocks of a simple YAML block. Anything else (nested maps,
 * anchors) is skipped: the `raw` text is there for a real YAML parser.
 */
function parseFrontmatterProperties(raw: string): FrontmatterProperty[] {
  const properties: FrontmatterProperty[] = []
  let list: string[] | null = null
  let block: { lines: string[]; join: string } | null = null
  let current: FrontmatterProperty | null = null
  const finish = () => {
    if (current && block) current.value = block.lines.join(block.join).trim()
    else if (current && list) current.value = list
    block = null
    list = null
  }
  for (const line of raw.split(/\r\n?|\n/)) {
    if (block && (/^\s/.test(line) || !line.trim())) {
      block.lines.push(line.trim())
      continue
    }
    if (!line.trim() || /^\s*#/.test(line)) continue
    const item = /^\s*-\s+(.*)$/.exec(line) ?? (/^\s*-$/.test(line) ? ["", ""] : null)
    if (item && current && list) {
      list.push(unquote(item[1] ?? ""))
      continue
    }
    const entry = /^([^\s#:-][^:]*?|"[^"]*"|'[^']*'):(?:[ \t]+(.*))?$/.exec(line)
    if (!entry) continue
    finish()
    const key = unquote(entry[1] ?? "")
    const value = (entry[2] ?? "").trim()
    current = { key, value: "" }
    properties.push(current)
    if (value === "") list = []
    else if (/^[|>][+-]?$/.test(value)) block = { lines: [], join: value.startsWith("|") ? "\n" : " " }
    else if (value.startsWith("[") && value.endsWith("]")) current.value = splitInline(value.slice(1, -1))
    else current.value = unquote(value)
  }
  finish()
  return properties.map((property) =>
    Array.isArray(property.value) && property.value.length === 0 ? { ...property, value: "" } : property,
  )
}

/** The leading YAML frontmatter of a Markdown document, or `null` when it has none. */
function parseFrontmatter(markdown: string): Frontmatter | null {
  const bounds = frontmatterBounds(markdown)
  if (!bounds) return null
  const raw = markdown.slice(bounds.contentFrom, bounds.contentTo)
  return { from: bounds.from, to: bounds.to, raw, properties: parseFrontmatterProperties(raw) }
}

export { frontmatterBounds, parseFrontmatter, parseFrontmatterProperties }
export type { Frontmatter, FrontmatterProperty }

import type { SyntaxNode, Tree } from "@lezer/common"

import { frontmatterBounds } from "@/components/ui/markdown-frontmatter"
import { markdownParser } from "@/components/ui/markdown-syntax"

type MarkdownHeading = {
  level: number
  /** The heading as plain text: marks dropped, a wikilink as its label. */
  text: string
  /**
   * Its anchor, unique in the document: the text lowercased, punctuation dropped, spaces as `-`, and `-1`, `-2`…
   * after a repeat. `MarkdownView` puts it on the rendered heading as `data-slug`.
   */
  slug: string
  /** The line it starts on, from 1, as the editor counts lines. */
  line: number
  /** Offsets in the Markdown: the heading's start and end, and where its text starts after the `#` marks. */
  from: number
  to: number
  textFrom: number
}

const MARKS = new Set([
  "HeaderMark",
  "EmphasisMark",
  "CodeMark",
  "LinkMark",
  "URL",
  "LinkTitle",
  "LinkLabel",
  "StrikethroughMark",
  "WikilinkMark",
  "WikilinkPipe",
  "EmbedMark",
])

function plainText(src: string, node: SyntaxNode, from = node.from, to = node.to): string {
  if (node.name === "Wikilink" || node.name === "Embed") {
    const label = node.getChild("WikilinkLabel") ?? node.getChild("WikilinkTarget")
    return label ? src.slice(label.from, label.to) : ""
  }
  if (node.name === "Escape") return src.slice(node.from + 1, node.to)
  let text = ""
  let pos = from
  for (let child = node.firstChild; child; child = child.nextSibling) {
    if (child.to <= from || child.from >= to) continue
    text += src.slice(pos, child.from)
    if (!MARKS.has(child.name)) text += plainText(src, child)
    pos = child.to
  }
  return text + src.slice(pos, to)
}

// Headings sit at the top level or inside these; the walk skips everything else.
const CONTAINERS = new Set(["Document", "Blockquote", "BulletList", "OrderedList", "ListItem"])

// An empty heading still needs an anchor; it isn't shown anywhere.
function slugify(text: string) {
  const slug = text
    .toLowerCase()
    .replace(/[^\p{L}\p{M}\p{N}\s_-]/gu, "")
    .trim()
    .replace(/\s/g, "-")
  return slug || "heading"
}

/** GitHub's rule: a slug already taken gets `-1`, `-2`… after it, in document order. */
function createSlugger() {
  const counts = new Map<string, number>()
  return (text: string) => {
    const base = slugify(text)
    let slug = base
    while (counts.has(slug)) {
      const count = (counts.get(base) ?? 0) + 1
      counts.set(base, count)
      slug = `${base}-${String(count)}`
    }
    counts.set(slug, 0)
    return slug
  }
}

/** Every heading of a Markdown document in order, frontmatter left out, for an outline or a table of contents. */
function extractHeadings(markdown: string): MarkdownHeading[] {
  return headingsOf(markdown, markdownParser.parse(markdown))
}

/** The headings of `markdown` from its parse tree, as `extractHeadings` gives them. */
function headingsOf(markdown: string, tree: Tree): MarkdownHeading[] {
  const slug = createSlugger()
  const start = frontmatterBounds(markdown)?.to ?? 0
  const headings: MarkdownHeading[] = []
  let line = 1
  let counted = 0
  const lineAt = (pos: number) => {
    for (
      let index = markdown.indexOf("\n", counted);
      index >= 0 && index < pos;
      index = markdown.indexOf("\n", index + 1)
    ) {
      line++
      counted = index + 1
    }
    if (counted < pos) counted = pos
    return line
  }
  tree.iterate({
    from: start,
    enter(ref) {
      const match = /^(ATX|Setext)Heading(\d)$/.exec(ref.name)
      if (!match) return CONTAINERS.has(ref.name) ? undefined : false
      if (ref.from < start) return false
      const node = ref.node
      const marks = node.getChildren("HeaderMark")
      const atx = match[1] === "ATX"
      const textFrom = atx ? (marks[0]?.to ?? node.from) : node.from
      const textTo = atx ? (marks[1]?.from ?? node.to) : (marks[0]?.from ?? node.to)
      const contentStart = atx
        ? textFrom + (/^[ \t]*/.exec(markdown.slice(textFrom, textTo))?.[0].length ?? 0)
        : textFrom
      const text = plainText(markdown, node, textFrom, textTo).replace(/\s+/g, " ").trim()
      headings.push({
        level: Number(match[2]),
        text,
        slug: slug(text),
        line: lineAt(node.from),
        from: node.from,
        to: node.to,
        textFrom: contentStart,
      })
      return false
    },
  })
  return headings
}

export { extractHeadings, headingsOf }
export type { MarkdownHeading }

import {
  parser as commonmark,
  Strikethrough,
  Table,
  TaskList,
  type InlineContext,
  type MarkdownConfig,
} from "@lezer/markdown"

const EXCLAMATION = 33
const OPEN_BRACKET = 91
const CLOSE_BRACKET = 93
const PIPE = 124
const NEWLINE = 10

/** `[[target|label]]` from `start + open`, as a node named `name` whose marks are `mark`; -1 when it isn't one. */
function parseTarget(cx: InlineContext, start: number, open: number, name: string, mark: string) {
  let pipe = -1
  for (let pos = start + open; pos < cx.end; pos++) {
    const char = cx.char(pos)
    if (char === NEWLINE || char === OPEN_BRACKET) return -1
    if (char === PIPE && pipe < 0) pipe = pos
    if (char !== CLOSE_BRACKET) continue
    if (cx.char(pos + 1) !== CLOSE_BRACKET) return -1
    const targetEnd = pipe < 0 ? pos : pipe
    if (targetEnd === start + open || cx.slice(start + open, targetEnd).trim() === "") return -1
    const children = [cx.elt(mark, start, start + open), cx.elt("WikilinkTarget", start + open, targetEnd)]
    if (pipe >= 0) {
      children.push(cx.elt("WikilinkPipe", pipe, pipe + 1))
      if (pos > pipe + 1) children.push(cx.elt("WikilinkLabel", pipe + 1, pos))
    }
    children.push(cx.elt(mark, pos, pos + 2))
    return cx.addElement(cx.elt(name, start, pos + 2, children))
  }
  return -1
}

const Wikilink: MarkdownConfig = {
  defineNodes: ["Wikilink", "WikilinkMark", "WikilinkTarget", "WikilinkPipe", "WikilinkLabel", "Embed", "EmbedMark"],
  parseInline: [
    {
      name: "Embed",
      before: "Image",
      parse(cx, next, start) {
        if (next !== EXCLAMATION || cx.char(start + 1) !== OPEN_BRACKET || cx.char(start + 2) !== OPEN_BRACKET) {
          return -1
        }
        return parseTarget(cx, start, 3, "Embed", "EmbedMark")
      },
    },
    {
      name: "Wikilink",
      before: "Link",
      parse(cx, next, start) {
        if (next !== OPEN_BRACKET || cx.char(start + 1) !== OPEN_BRACKET) return -1
        return parseTarget(cx, start, 2, "Wikilink", "WikilinkMark")
      },
    },
  ],
}

const markdownExtensions = [Table, TaskList, Strikethrough, Wikilink]
const markdownParser = commonmark.configure(markdownExtensions)

type WikilinkResolution = { exists: boolean; label?: string }
type WikilinkResolver = (slug: string) => WikilinkResolution

function wikilinkText(slug: string, label?: string) {
  return label && label !== slug ? `[[${slug}|${label}]]` : `[[${slug}]]`
}

export { markdownExtensions, markdownParser, Wikilink, wikilinkText }
export type { WikilinkResolution, WikilinkResolver }

import type { SyntaxNode } from "@lezer/common"
import type { ReactNode } from "react"

import { CodeBlock } from "@/components/ui/code-block"
import { Link } from "@/components/ui/link"
import type { Frontmatter } from "@/components/ui/markdown-frontmatter"
import type { RenderContext as Context } from "@/components/ui/markdown-view-render"

const slice = (cx: Context, node: { from: number; to: number }) => cx.src.slice(node.from, node.to)

function wikilinkParts(cx: Context, node: SyntaxNode) {
  const target = node.getChild("WikilinkTarget")
  const label = node.getChild("WikilinkLabel")
  return { slug: target ? slice(cx, target).trim() : "", alias: label ? slice(cx, label) : undefined }
}

/**
 * A wikilink with an address is a Link, so fast links, hash routes and agents' `follow` work, and
 * `onWikilinkClick` takes its plain clicks. Without an address, the callback makes it a button agents can follow.
 */
function wikilink(cx: Context, key: number, slug: string, alias: string | undefined, slot: string) {
  const resolution = cx.resolveWikilink?.(slug) ?? { exists: true }
  const text = alias ?? resolution.label ?? slug
  const href = resolution.exists ? cx.wikilinkHref?.(slug) : undefined
  const { onWikilinkClick } = cx
  // A Link with onFollow takes the link primitive's data-slot, so data-wikilink is what styles and finds it.
  const props = {
    "data-slot": slot,
    "data-wikilink": slot === "markdown-embed" ? "embed" : "link",
    "data-target": slug,
    "data-unresolved": resolution.exists ? undefined : "",
  }
  const onFollow =
    onWikilinkClick && ((_href: string, details: { event?: Event }) => onWikilinkClick(slug, details.event))
  if (href) {
    return (
      <Link key={key} href={href} onFollow={onFollow} {...props}>
        {text}
      </Link>
    )
  }
  if (onFollow) {
    return (
      // oxlint-disable-next-line jsx-a11y/control-has-associated-label -- the Link renders the wikilink's text inside it
      <Link key={key} render={<button type="button" />} fast={false} onFollow={onFollow} {...props}>
        {text}
      </Link>
    )
  }
  return (
    <span key={key} {...props}>
      {text}
    </span>
  )
}

/** A paragraph that holds only an embed renders it as a block, so what `renderEmbed` returns isn't inside a <p>. */
function renderSoleEmbed(cx: Context, paragraph: SyntaxNode): ReactNode {
  const only = paragraph.firstChild
  if (!only || only.nextSibling || only.name !== "Embed" || !cx.renderEmbed) return null
  const outside = cx.src.slice(paragraph.from, only.from) + cx.src.slice(only.to, paragraph.to)
  if (outside.trim()) return null
  const { slug, alias } = wikilinkParts(cx, only)
  return (
    <div key={paragraph.from} data-slot="markdown-embed" data-target={slug}>
      {cx.renderEmbed(slug, alias)}
    </div>
  )
}

function renderFrontmatter(cx: Context, frontmatter: Frontmatter): ReactNode {
  if (cx.renderFrontmatter) return cx.renderFrontmatter(frontmatter)
  if (cx.frontmatter === "raw") return <CodeBlock code={frontmatter.raw} language="yaml" labels={cx.codeLabels} />
  if (cx.frontmatter !== "properties" || !frontmatter.properties.length) return null
  return (
    <dl data-slot="markdown-properties" aria-label={cx.frontmatterLabel}>
      {frontmatter.properties.map((property, index) => (
        <div key={`${property.key}.${String(index)}`} data-slot="markdown-property">
          <dt>{property.key}</dt>
          <dd>{typeof property.value === "string" ? property.value : property.value.join(", ")}</dd>
        </div>
      ))}
    </dl>
  )
}

export { renderFrontmatter, renderSoleEmbed, wikilink, wikilinkParts }

import { TreeFragment, type SyntaxNode, type Tree } from "@lezer/common"
import type { ReactNode } from "react"

import { CodeBlock, type CodeBlockLabels } from "@/components/ui/code-block"
import { Link } from "@/components/ui/link"
import { parseFrontmatter, type Frontmatter } from "@/components/ui/markdown-frontmatter"
import { headingsOf } from "@/components/ui/markdown-outline"
import { renderFrontmatter, renderSoleEmbed, wikilink, wikilinkParts } from "@/components/ui/markdown-view-links"
import { markdownParser, type WikilinkResolver } from "@/components/ui/markdown-syntax"

type FrontmatterDisplay = "hide" | "properties" | "raw"

type ImageSize = { width: number; height?: number }
/** `alt|300x200` or `alt|300`, as Obsidian writes an image's size in its alt text. */
function sizeInAlt(text: string): { alt: string; size?: ImageSize } {
  const [, alt = "", width, height] = /^(.*?)\|(\d+)(?:x(\d+))?$/.exec(text) ?? []
  if (width === undefined) return { alt: text }
  return { alt: alt.trim(), size: { width: Number(width), ...(height ? { height: Number(height) } : {}) } }
}

type RenderOptions = {
  resolveWikilink?: WikilinkResolver
  wikilinkHref?: (slug: string) => string | undefined
  onWikilinkClick?: (target: string, event: Event | undefined) => void
  renderEmbed?: (target: string, alias: string | undefined) => ReactNode
  imageSize?: (src: string, alt: string) => ImageSize | undefined
  frontmatter?: FrontmatterDisplay
  renderFrontmatter?: (frontmatter: Frontmatter) => ReactNode
  frontmatterLabel?: string
  taskLabel: string
  /** Names for fenced code blocks and their copy buttons. */
  codeLabels?: Partial<CodeBlockLabels>
  /** Puts each table cell's offset in the source on `data-source-from`. */
  sourcePositions?: boolean
}

type Context = RenderOptions & {
  src: string
  refs: Map<string, { href: string; title?: string }>
  /** Each heading's slug, by its start: the same ones `extractHeadings` gives. */
  slugs?: Map<number, string>
}

const ENTITIES: Record<string, string> = {
  amp: "&",
  lt: "<",
  gt: ">",
  quot: '"',
  apos: "'",
  nbsp: " ",
  copy: "©",
  reg: "®",
  hellip: "…",
  mdash: "—",
  ndash: "–",
}

function decodeEntity(entity: string) {
  const numeric = /^&#(x?)([0-9a-f]+);$/i.exec(entity)
  if (numeric) {
    const code = Number.parseInt(numeric[2] ?? "", numeric[1] ? 16 : 10)
    return code > 0 && code <= 0x10ffff ? String.fromCodePoint(code) : "�"
  }
  return ENTITIES[entity.slice(1, -1)] ?? entity
}

const unescape = (text: string) =>
  text.replace(/\\([!-/:-@[-`{-~])/g, "$1").replace(/&(?:#x?[0-9a-f]+|[a-z][a-z0-9]*);/gi, decodeEntity)

/** Only these schemes become links; anything else, like `javascript:`, renders as plain text. */
function safeHref(raw: string) {
  const href = unescape(raw.trim().replace(/^<|>$/g, ""))
  const scheme = /^([a-z][a-z0-9+.-]*):/i.exec([...href].filter((char) => char > " ").join(""))?.[1]?.toLowerCase()
  return !scheme || ["http", "https", "mailto", "tel"].includes(scheme) ? href : undefined
}

const normalizeLabel = (label: string) => label.trim().replace(/\s+/g, " ").toLowerCase()
const slice = (cx: Context, node: { from: number; to: number }) => cx.src.slice(node.from, node.to)
const children = (node: SyntaxNode) => {
  const list: SyntaxNode[] = []
  for (let child = node.firstChild; child; child = child.nextSibling) list.push(child)
  return list
}

function inline(cx: Context, node: SyntaxNode, from = node.from, to = node.to, skip = new Set<string>()): ReactNode[] {
  const out: ReactNode[] = []
  let pos = from
  for (const child of children(node)) {
    if (child.to <= from || child.from >= to) continue
    if (child.from > pos) out.push(cx.src.slice(pos, child.from))
    if (!skip.has(child.name) && child.name !== "QuoteMark") out.push(renderInline(cx, child))
    pos = child.to
  }
  if (pos < to) out.push(cx.src.slice(pos, to))
  return out
}

function linkParts(cx: Context, node: SyntaxNode) {
  const marks = node.getChildren("LinkMark")
  const labelFrom = marks[0]?.to ?? node.from
  const labelTo = marks[1]?.from ?? node.to
  const url = node.getChild("URL")
  const title = node.getChild("LinkTitle")
  if (url)
    return {
      labelFrom,
      labelTo,
      href: safeHref(slice(cx, url)),
      title: title ? unescape(slice(cx, title).slice(1, -1)) : undefined,
      found: true,
    }
  const reference = node.getChild("LinkLabel")
  const key = normalizeLabel(
    reference && reference.to - reference.from > 2
      ? slice(cx, reference).slice(1, -1)
      : cx.src.slice(labelFrom, labelTo),
  )
  const ref = cx.refs.get(key)
  return { labelFrom, labelTo, href: ref ? safeHref(ref.href) : undefined, title: ref?.title, found: Boolean(ref) }
}

function renderInline(cx: Context, node: SyntaxNode): ReactNode {
  const key = node.from
  switch (node.name) {
    case "Emphasis":
      return <em key={key}>{inline(cx, node, node.from, node.to, new Set(["EmphasisMark"]))}</em>
    case "StrongEmphasis":
      return <strong key={key}>{inline(cx, node, node.from, node.to, new Set(["EmphasisMark"]))}</strong>
    case "Strikethrough":
      return <del key={key}>{inline(cx, node, node.from, node.to, new Set(["StrikethroughMark"]))}</del>
    case "InlineCode": {
      const marks = node.getChildren("CodeMark")
      let text = cx.src.slice(marks[0]?.to ?? node.from, marks[1]?.from ?? node.to).replace(/\r?\n/g, " ")
      if (/^ .*[^ ].* $/s.test(text)) text = text.slice(1, -1)
      return <code key={key}>{text}</code>
    }
    case "Link":
    case "Image": {
      const parts = linkParts(cx, node)
      if (!parts.found) return slice(cx, node)
      const label = inline(
        cx,
        node,
        parts.labelFrom,
        parts.labelTo,
        new Set(["LinkMark", "URL", "LinkTitle", "LinkLabel"]),
      )
      if (node.name === "Image") {
        // With a width and height the box is reserved before the image loads (CSS keeps `height: auto`), so text
        // below it doesn't move when it arrives.
        const written = sizeInAlt(cx.src.slice(parts.labelFrom, parts.labelTo))
        const size = written.size ?? (parts.href ? cx.imageSize?.(parts.href, written.alt) : undefined)
        return (
          <img
            key={key}
            src={parts.href}
            alt={written.alt}
            title={parts.title}
            width={size?.width}
            height={size?.height}
            loading="lazy"
            decoding="async"
          />
        )
      }
      return parts.href === undefined ? (
        <span key={key}>{label}</span>
      ) : (
        <Link key={key} href={parts.href} title={parts.title}>
          {label}
        </Link>
      )
    }
    case "Autolink": {
      const url = node.getChild("URL")
      const text = url ? slice(cx, url) : slice(cx, node)
      const href = safeHref(/^[^\s@:]+@/.test(text) ? `mailto:${text}` : text)
      return href ? (
        <Link key={key} href={href}>
          {text}
        </Link>
      ) : (
        text
      )
    }
    case "Escape":
      return cx.src.slice(node.from + 1, node.to)
    case "Entity":
      return decodeEntity(slice(cx, node))
    case "HardBreak":
      return <br key={key} />
    case "Wikilink": {
      const { slug, alias } = wikilinkParts(cx, node)
      return wikilink(cx, key, slug, alias, "markdown-wikilink")
    }
    case "Embed": {
      const { slug, alias } = wikilinkParts(cx, node)
      if (!cx.renderEmbed) return wikilink(cx, key, slug, alias, "markdown-embed")
      return (
        <span key={key} data-slot="markdown-embed" data-target={slug}>
          {cx.renderEmbed(slug, alias)}
        </span>
      )
    }
    default:
      return slice(cx, node)
  }
}

function isTight(cx: Context, list: SyntaxNode) {
  const items = children(list)
  return items.every((item, index) => {
    const next = items[index + 1]
    if (next && /\n[ \t]*\r?\n/.test(cx.src.slice(item.to, next.from))) return false
    const parts = children(item).filter((child) => child.name !== "ListMark")
    return parts.every((part, i) => !parts[i + 1] || !/\n[ \t]*\r?\n/.test(cx.src.slice(part.to, parts[i + 1]!.from)))
  })
}

function blocks(cx: Context, node: SyntaxNode, tight = false): ReactNode[] {
  return children(node).map((child) => renderBlock(cx, child, tight))
}

function renderBlock(cx: Context, node: SyntaxNode, tight = false): ReactNode {
  const key = node.from
  const heading = /^(ATX|Setext)Heading(\d)$/.exec(node.name)
  if (heading) {
    const Tag = `h${heading[2]}` as "h1"
    const marks = node.getChildren("HeaderMark")
    const from = heading[1] === "ATX" ? (marks[0]?.to ?? node.from) : node.from
    const to = heading[1] === "ATX" ? (marks[1]?.from ?? node.to) : (marks[0]?.from ?? node.to)
    return (
      <Tag key={key} data-slug={cx.slugs?.get(node.from)}>
        {trim(inline(cx, node, from, to, new Set(["HeaderMark"])))}
      </Tag>
    )
  }
  switch (node.name) {
    case "Paragraph":
      return (
        renderSoleEmbed(cx, node) ??
        (tight ? <span key={key}>{trim(inline(cx, node))}</span> : <p key={key}>{trim(inline(cx, node))}</p>)
      )
    case "Blockquote":
      return <blockquote key={key}>{blocks(cx, node)}</blockquote>
    case "BulletList":
      return <ul key={key}>{blocks(cx, node, isTight(cx, node))}</ul>
    case "OrderedList": {
      const start = Number.parseInt(slice(cx, node.getChild("ListItem")?.getChild("ListMark") ?? node), 10)
      return (
        <ol key={key} start={start === 1 || Number.isNaN(start) ? undefined : start}>
          {blocks(cx, node, isTight(cx, node))}
        </ol>
      )
    }
    case "ListItem":
      return <li key={key}>{blocks(cx, node, tight)}</li>
    case "Task": {
      const marker = node.getChild("TaskMarker")
      const checked = marker ? /x/i.test(slice(cx, marker)) : false
      return (
        <span key={key} data-slot="markdown-view-task">
          <input type="checkbox" checked={checked} readOnly disabled aria-label={cx.taskLabel} />
          <span>{trim(inline(cx, node, marker?.to ?? node.from, node.to, new Set(["TaskMarker"])))}</span>
        </span>
      )
    }
    case "FencedCode": {
      const info = node.getChild("CodeInfo")
      const text = node.getChild("CodeText")
      return (
        <CodeBlock
          key={key}
          code={text ? slice(cx, text) : ""}
          language={info ? slice(cx, info) : undefined}
          labels={cx.codeLabels}
        />
      )
    }
    case "CodeBlock":
      return <CodeBlock key={key} code={slice(cx, node).replace(/^( {1,4}|\t)/gm, "")} labels={cx.codeLabels} />
    case "HorizontalRule":
      return <hr key={key} />
    case "Table":
      return renderTable(cx, node)
    case "LinkReference":
    case "ListMark":
    case "QuoteMark":
      return null
    default:
      return (
        <pre key={key} data-slot="markdown-view-raw">
          {slice(cx, node)}
        </pre>
      )
  }
}

function renderTable(cx: Context, node: SyntaxNode) {
  const header = node.getChild("TableHeader")
  const delimiter = node.getChild("TableDelimiter")
  const delimiterLine = delimiter ? slice(cx, delimiter) : ""
  const align = delimiterLine
    .replace(/^\s*\|/, "")
    .replace(/\|\s*$/, "")
    .split("|")
    .map((cell) => {
      const value = cell.trim()
      if (value.startsWith(":") && value.endsWith(":")) return "center" as const
      if (value.endsWith(":")) return "right" as const
      return value.startsWith(":") ? ("left" as const) : undefined
    })
  const columns = align.map((textAlign, column) => ({ textAlign, column }))
  const cells = (row: SyntaxNode, Tag: "th" | "td") => {
    const list = row.getChildren("TableCell")
    return columns.map(({ textAlign, column }) => {
      const cell = list[column]
      return (
        <Tag
          key={column}
          style={textAlign ? { textAlign } : undefined}
          data-source-from={cx.sourcePositions ? (cell?.from ?? row.from) : undefined}
        >
          {cell ? trim(inline(cx, cell)) : null}
        </Tag>
      )
    })
  }
  return (
    <table key={node.from}>
      {header && (
        <thead>
          <tr>{cells(header, "th")}</tr>
        </thead>
      )}
      <tbody>
        {node.getChildren("TableRow").map((row) => (
          <tr key={row.from}>{cells(row, "td")}</tr>
        ))}
      </tbody>
    </table>
  )
}

function trim(nodes: ReactNode[]) {
  const first = nodes[0]
  if (typeof first === "string") nodes[0] = first.trimStart()
  const last = nodes.at(-1)
  if (typeof last === "string") nodes[nodes.length - 1] = last.trimEnd()
  return nodes
}

function collectReferences(cx: Context, top: SyntaxNode) {
  top.cursor().iterate((ref) => {
    if (ref.name !== "LinkReference") return
    const node = ref.node
    const label = node.getChild("LinkLabel")
    const url = node.getChild("URL")
    const title = node.getChild("LinkTitle")
    if (!label || !url) return false
    const key = normalizeLabel(slice(cx, label).slice(1, -1))
    if (!cx.refs.has(key))
      cx.refs.set(key, { href: slice(cx, url), title: title ? unescape(slice(cx, title).slice(1, -1)) : undefined })
    return false
  })
}

function hash(text: string) {
  let value = 0x811c9dc5
  for (let index = 0; index < text.length; index++) value = Math.imul(value ^ text.charCodeAt(index), 0x01000193)
  return (value >>> 0).toString(36)
}

/** `anchors` are the slugs of the headings in the block, which a repeated heading elsewhere can change. */
type MarkdownBlock = { key: string; text: string; anchors: string; render: () => ReactNode }

/**
 * Parses once and returns the top-level blocks, each keyed by a hash of its source and how many identical
 * blocks came before it, so a key survives edits elsewhere in the document.
 */
type Parsed = { src: string; tree: Tree }

/** Reuses the previous parse for everything outside the one edited range, as an editor's parse does. */
function parse(src: string, previous?: Parsed) {
  if (!previous) return markdownParser.parse(src)
  const old = previous.src
  const max = Math.min(old.length, src.length)
  let start = 0
  while (start < max && old.charCodeAt(start) === src.charCodeAt(start)) start++
  let end = 0
  while (end < max - start && old.charCodeAt(old.length - 1 - end) === src.charCodeAt(src.length - 1 - end)) end++
  const change = { fromA: start, toA: old.length - end, fromB: start, toB: src.length - end }
  const fragments = TreeFragment.applyChanges(TreeFragment.addTree(previous.tree), [change])
  return markdownParser.parse(src, fragments)
}

function markdownBlocks(src: string, options: RenderOptions, previous?: Parsed) {
  const tree = previous?.src === src ? previous.tree : parse(src, previous)
  const headings = headingsOf(src, tree)
  const cx: Context = {
    ...options,
    src,
    refs: new Map(),
    slugs: new Map(headings.map((heading) => [heading.from, heading.slug])),
  }
  collectReferences(cx, tree.topNode)
  const seen = new Map<string, number>()
  const block = (text: string, render: () => ReactNode, anchors = ""): MarkdownBlock => {
    const digest = hash(text)
    const count = seen.get(digest) ?? 0
    seen.set(digest, count + 1)
    return { key: `${digest}.${String(count)}`, text, anchors, render }
  }
  // Blocks and headings are both in document order, so one pass hands each block its headings.
  let next = 0
  const anchorsIn = (node: SyntaxNode) => {
    const slugs: string[] = []
    while (next < headings.length && headings[next]!.from < node.from) next++
    for (; next < headings.length && headings[next]!.from < node.to; next++) slugs.push(headings[next]!.slug)
    return slugs.join(" ")
  }
  // Leading YAML parses as a rule and a setext heading; those nodes are left out and it renders as one block.
  const frontmatter = parseFrontmatter(src)
  const nodes = children(tree.topNode).filter((node) => !frontmatter || node.to > frontmatter.to)
  const list: MarkdownBlock[] = nodes.map((node) =>
    block(slice(cx, node), () => renderBlock(cx, node), anchorsIn(node)),
  )
  if (frontmatter && (cx.renderFrontmatter || (cx.frontmatter ?? "hide") !== "hide")) {
    const source = `${cx.frontmatter ?? "custom"}\n${src.slice(frontmatter.from, frontmatter.to)}`
    list.unshift(block(source, () => renderFrontmatter(cx, frontmatter)))
  }
  const references = hash(JSON.stringify([...cx.refs]))
  return { blocks: list, references, parsed: { src, tree } satisfies Parsed }
}

function renderMarkdown(src: string, options: RenderOptions): ReactNode[] {
  return markdownBlocks(src, options).blocks.map((block) => block.render())
}

export { markdownBlocks, renderMarkdown, safeHref }
export type { Context as RenderContext, FrontmatterDisplay, MarkdownBlock, Parsed, RenderOptions }
